(function(){
'use strict';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let loading=false,saving=false;
const db=()=>window.VolleySupabase?.getClient?.()||null;
const state=()=>typeof appState!=='undefined'?appState:null;
const call=(n,...a)=>{try{if(typeof window[n]==='function')window[n](...a)}catch(_){}};
function ev(id){const s=state();if(!s)return null;const x=String(id||'');return(s.events||[]).find(e=>[e.id,e.supabaseId,e.supabase_id,e.legacy_id,e.legacyId].filter(Boolean).map(String).includes(x))||null;}
function pl(id){const s=state();if(!s)return null;const x=String(id||'');return(s.players||[]).find(p=>[p.id,p.supabaseId,p.legacy_id,p.legacyId,p.profile_id].filter(Boolean).map(String).includes(x))||null;}
function isTraining(e){const t=String(e?.type||e?.event_type||e?.eventType||e?.title||'').toLowerCase();return t.includes('entrenamiento')||t==='training';}
function endTime(e){if(!e)return null;if(e.ends_at||e.endsAt){const d=new Date(e.ends_at||e.endsAt);if(!Number.isNaN(d.getTime()))return d;}if(e.date){const start=new Date(`${e.date}T${e.time||'00:00'}:00`);const mins=Number(e.duration||e.rawPayload?.duration||120);if(!Number.isNaN(start.getTime()))return new Date(start.getTime()+mins*60000);}return null;}
function currentPlayer(){try{const u=getCurrentUser?.();if(!u?.playerId&&!u?.supabasePlayerId)return null;return pl(u.playerId)||pl(u.supabasePlayerId)}catch(_){return null;}}
function hasPlayerRpe(e,p){return (state()?.trainingRPEs||[]).some(r=>String(r.eventId)===String(e.id)&&String(r.playerId)===String(p.id)&&Number.isFinite(Number(r.rpeVal)));}
function pendingForCurrentPlayer(){const s=state(),p=currentPlayer();if(!s||!p)return[];const now=Date.now();return(s.events||[]).filter(e=>{const end=endTime(e);return isTraining(e)&&end&&end.getTime()<=now&&!hasPlayerRpe(e,p);}).sort((a,b)=>(endTime(b)?.getTime()||0)-(endTime(a)?.getTime()||0));}
function removeLegacyPendingRpeNotices(){const root=document.getElementById('home-dashboard');if(!root)return;[...root.querySelectorAll('*')].forEach(el=>{if(el.id==='rpe-pending-authoritative')return;const txt=String(el.textContent||'').toLowerCase();if(txt.includes('rpe')&&(txt.includes('te falta')||txt.includes('pendiente')||txt.includes('enviar el rpe'))){const card=el.closest('.dashboard-action-card,.dashboard-card,.home-dashboard-card,.dashboard-alert,.player-home-card')||el;if(card.id!=='rpe-pending-authoritative')card.style.display='none';}});}
function paintPendingNotice(){const root=document.getElementById('home-dashboard');if(!root)return;removeLegacyPendingRpeNotices();let card=document.getElementById('rpe-pending-authoritative');const u=(()=>{try{return getCurrentUser?.()}catch(_){return null}})();if(!u?.playerId&&!u?.supabasePlayerId){card?.remove();return;}const pending=pendingForCurrentPlayer();const s=state();if(s)s.pendingRpeEventIds=pending.map(e=>e.id);if(!pending.length){card?.remove();return;}const latest=pending[0];if(!card){card=document.createElement('button');card.type='button';card.id='rpe-pending-authoritative';card.className='rpe-pending-authoritative';root.prepend(card);}card.onclick=()=>{call('openModule','training',{returnTarget:'home-portal'});setTimeout(()=>call('openSessionCenter',latest.id,'home-portal'),0);};card.innerHTML=`<span class="rpe-pending-icon">!</span><span><strong>Te falta enviar el RPE del entrenamiento</strong><small>${pending.length>1?`Tienes ${pending.length} sesiones pendientes.`:'La sesión ya ha terminado. Registra tu percepción del esfuerzo.'}</small></span><span class="rpe-pending-arrow">›</span>`;}
function injectPendingCss(){if(document.getElementById('rpe-pending-authoritative-css'))return;const s=document.createElement('style');s.id='rpe-pending-authoritative-css';s.textContent=`.rpe-pending-authoritative{width:100%;display:flex;align-items:center;gap:.8rem;text-align:left;border:1px solid #fed7aa;background:#fff7ed;color:#9a3412;border-radius:14px;padding:.9rem 1rem;margin:0 0 1rem;cursor:pointer}.rpe-pending-authoritative strong{display:block;font-size:.92rem}.rpe-pending-authoritative small{display:block;color:#78716c;margin-top:.15rem}.rpe-pending-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#f97316;color:white;font-weight:900;flex:none}.rpe-pending-arrow{margin-left:auto;font-size:1.6rem;color:#f97316}`;document.head.appendChild(s);}
async function eventUuid(id){const c=db(),e=ev(id);if(!c)return null;for(const v of[e?.id,e?.supabaseId,e?.supabase_id,id])if(UUID.test(String(v||'')))return String(v);const legacy=e?.legacy_id||e?.legacyId||id;const{data,error}=await c.from('events').select('id').eq('legacy_id',String(legacy)).maybeSingle();if(error)throw error;return data?.id||null;}
async function syncPlayers(){const c=db(),s=state();if(!c||!s)return;const{data,error}=await c.from('players').select('id,legacy_id,profile_id,active,profiles:profile_id(username)');if(error)throw error;for(const r of data||[]){if(r.active===false)continue;const p=(s.players||[]).find(x=>String(x.supabaseId||'')===r.id||String(x.id||'')===String(r.legacy_id||'')||String(x.legacy_id||x.legacyId||'')===String(r.legacy_id||'')||String(x.username||'').toLowerCase()===String(r.profiles?.username||'').toLowerCase());if(p){p.supabaseId=r.id;p.legacy_id=r.legacy_id||p.legacy_id;p.profile_id=r.profile_id||p.profile_id;}}}
async function load(opts={}){if(loading)return;const c=db(),s=state();if(!c||!s)return;loading=true;try{await syncPlayers();const{data,error}=await c.from('rpe_entries').select('id,event_id,player_id,coach_profile_id,score,source,created_at');if(error)throw error;s.trainingRPEs=[];for(const e of s.events||[]){delete e.rpe;e.coachRpe=NaN;e.coachRPE=NaN;}for(const r of data||[]){const e=ev(r.event_id);if(!e)continue;if(r.source==='coach'){e.coachRpe=Number(r.score);e.coachRPE=Number(r.score);continue;}const p=pl(r.player_id);if(!p)continue;s.trainingRPEs.push({id:r.id,eventId:e.id,playerId:p.id,rpeVal:Number(r.score),addedByCoach:r.source==='coach_for_player',source:r.source,supabaseEventId:r.event_id,supabasePlayerId:r.player_id});}s.pendingRpeEventIds=pendingForCurrentPlayer().map(e=>e.id);if(!opts.silent){call('renderTraining');call('renderHomeDashboard');call('renderTeamRpeSummary');}setTimeout(paintPendingNotice,0);return data||[];}finally{loading=false;}}
async function savePlayer(eventId,score){const c=db();if(!c||saving)return;saving=true;try{const eid=await eventUuid(eventId),ident=await window.VolleySupabase.getIdentity(),pid=ident?.data?.player?.id;if(!UUID.test(String(eid||''))||!UUID.test(String(pid||'')))throw new Error('No se encuentra la sesión o la jugadora.');const{data:e,error:ee}=await c.from('events').select('ends_at,starts_at,payload').eq('id',eid).single();if(ee)throw ee;let end=e.ends_at?new Date(e.ends_at):null;if(!end&&e.starts_at&&e.payload?.duration)end=new Date(new Date(e.starts_at).getTime()+Number(e.payload.duration)*60000);if(!end||end>new Date())throw new Error('Podrás enviar el RPE cuando haya terminado el entrenamiento.');const{data:old,error:oe}=await c.from('rpe_entries').select('id').eq('event_id',eid).eq('player_id',pid).maybeSingle();if(oe)throw oe;if(old)throw new Error('Tu RPE ya está registrado.');const{error}=await c.from('rpe_entries').insert({event_id:eid,player_id:pid,score:Number(score),source:'player'});if(error)throw error;await load({silent:true});call('renderTraining');call('renderHomeDashboard');setTimeout(paintPendingNotice,0);showToast?.(`Esfuerzo registrado: ${score}/10`);}catch(e){showToast?.(e.message||'No se pudo guardar el RPE.','error');}finally{saving=false;}}
async function saveCoach(eventId,score){const c=db();if(!c||saving)return;saving=true;try{const eid=await eventUuid(eventId),ident=await window.VolleySupabase.getIdentity(),cid=ident?.data?.profile?.id;if(!UUID.test(String(eid||''))||!UUID.test(String(cid||'')))throw new Error('No se encuentra la sesión o el entrenador.');const{data:old}=await c.from('rpe_entries').select('id').eq('event_id',eid).eq('coach_profile_id',cid).maybeSingle();if(old)throw new Error('Tu valoración ya está registrada.');const{error}=await c.from('rpe_entries').insert({event_id:eid,coach_profile_id:cid,player_id:null,score:Number(score),source:'coach'});if(error)throw error;await load({silent:true});call('renderTraining');call('renderHomeDashboard');showToast?.(`Valoración registrada: ${score}/10`);}catch(e){showToast?.(e.message||'No se pudo guardar la valoración.','error');}finally{saving=false;}}
async function saveForPlayer(eventId,playerId){const sel=document.getElementById(`coach-rpe-${eventId}-${playerId}`),score=Number(sel?.value),c=db();if(!c||saving||!Number.isFinite(score))return;saving=true;try{await syncPlayers();const eid=await eventUuid(eventId),p=pl(playerId),pid=p?.supabaseId;if(!UUID.test(String(eid||''))||!UUID.test(String(pid||'')))throw new Error('No se encuentra la jugadora.');const{data:old}=await c.from('rpe_entries').select('id,source').eq('event_id',eid).eq('player_id',pid).maybeSingle();if(old)throw new Error(old.source==='player'?'La jugadora ya ha contestado su RPE.':'Ese RPE ya está registrado.');const{error}=await c.from('rpe_entries').insert({event_id:eid,player_id:pid,score,source:'coach_for_player'});if(error)throw error;await load({silent:true});call('renderTraining');call('renderTeamRpeSummary');showToast?.('RPE añadido correctamente.');}catch(e){showToast?.(e.message||'No se pudo guardar el RPE.','error');}finally{saving=false;}}
function install(){const wait=()=>{if(!window.VolleySupabase||typeof window.setTrainingRPE!=='function'){setTimeout(wait,200);return;}injectPendingCss();window.loadRpeFromSupabase=load;window.getPendingRpeEvents=()=>pendingForCurrentPlayer().slice();window.isRpeSubmissionWindowOpen=e=>{const end=endTime(e);return !!(e&&end&&end<=new Date());};window.setTrainingRPE=(eventId,val,mode=null)=>{const u=getCurrentUser?.();const coach=mode==='coach'||(!u?.playerId&&isCoachUser?.());return coach?saveCoach(eventId,val):savePlayer(eventId,val);};window.addPlayerRpeByCoach=saveForPlayer;const baseRender=window.renderHomeDashboard;if(typeof baseRender==='function'&&!baseRender.__rpeAuthoritativeWrapped){const wrapped=function(){const out=baseRender.apply(this,arguments);setTimeout(paintPendingNotice,0);return out;};wrapped.__rpeAuthoritativeWrapped=true;window.renderHomeDashboard=wrapped;}void load({silent:false});const c=db();c?.channel('rpe-authoritative-live').on('postgres_changes',{event:'*',schema:'public',table:'rpe_entries'},()=>void load({silent:false})).subscribe();setInterval(()=>void load({silent:true}),5000);};setTimeout(wait,1400);}install();
})();